SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷113·太祖本纪四·广顺三年八月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfe4b4148ad7d1e2ee8fc2e5d5c0cfad4d17a33c/content/books/zizhi-tongjian/vol-291/year-0953/part-04/sources/library/jiuwudaishi-113-august-953/source.txt", "note": "《旧五代史》卷113·太祖本纪四·广顺三年八月，段落 jiu-wudaishi-205deb4a7860-p002691；已核上下文及传主，纸本及异文待核。", "id": "73569e95-4a6b-584f-9b47-a54723d530d4"}, {"title": "旧五代史·卷113·太祖本纪四·广顺三年十二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfe4b4148ad7d1e2ee8fc2e5d5c0cfad4d17a33c/content/books/zizhi-tongjian/vol-291/year-0953/part-04/sources/library/jiuwudaishi-113-december-953/source.txt", "note": "《旧五代史》卷113·太祖本纪四·广顺三年十二月，段落 jiu-wudaishi-205deb4a7860-p002695；已核上下文及传主，纸本及异文待核。", "id": "b020b38e-e129-5fc3-9a1e-c8c9391c12fc"}, {"title": "旧五代史·卷113·太祖本纪四·广顺三年十月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfe4b4148ad7d1e2ee8fc2e5d5c0cfad4d17a33c/content/books/zizhi-tongjian/vol-291/year-0953/part-04/sources/library/jiuwudaishi-113-october-953/source.txt", "note": "《旧五代史》卷113·太祖本纪四·广顺三年十月，段落 jiu-wudaishi-205deb4a7860-p002693；已核上下文及传主，纸本及异文待核。", "id": "9536a014-8e03-5749-b3b3-d72ab3926b94"}, {"title": "旧五代史·卷113·太祖本纪四·广顺三年九月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfe4b4148ad7d1e2ee8fc2e5d5c0cfad4d17a33c/content/books/zizhi-tongjian/vol-291/year-0953/part-04/sources/library/jiuwudaishi-113-september-953/source.txt", "note": "《旧五代史》卷113·太祖本纪四·广顺三年九月，段落 jiu-wudaishi-205deb4a7860-p002692；已核上下文及传主，纸本及异文待核。", "id": "a24b742b-c7aa-5b52-af13-e9dee6edb093"}, {"title": "新五代史·卷65·南汉世家第五·乾和十一年五子册封", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfe4b4148ad7d1e2ee8fc2e5d5c0cfad4d17a33c/content/books/zizhi-tongjian/vol-291/year-0953/part-04/sources/library/xinwudaishi-65-five-princes/source.txt", "note": "《新五代史》卷65·南汉世家第五·乾和十一年五子册封，段落 xin-wudaishi-b08f244b9241-p003288；已核上下文及传主，纸本及异文待核。", "id": "b3c06371-4226-5c1a-966a-f761bfe576d7"}, {"title": "新五代史·卷65·南汉世家第五·刘鋹初名", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfe4b4148ad7d1e2ee8fc2e5d5c0cfad4d17a33c/content/books/zizhi-tongjian/vol-291/year-0953/part-04/sources/library/xinwudaishi-65-liuchang-name/source.txt", "note": "《新五代史》卷65·南汉世家第五·刘鋹初名，段落 xin-wudaishi-b08f244b9241-p003292；已核上下文及传主，纸本及异文待核。", "id": "b83c5ed1-82a1-536c-b380-2836d8cfbb26"}, {"title": "新五代史·卷65·南汉世家第五·刘晟旧名", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfe4b4148ad7d1e2ee8fc2e5d5c0cfad4d17a33c/content/books/zizhi-tongjian/vol-291/year-0953/part-04/sources/library/xinwudaishi-65-liusheng-name/source.txt", "note": "《新五代史》卷65·南汉世家第五·刘晟旧名，段落 xin-wudaishi-b08f244b9241-p003281；已核上下文及传主，纸本及异文待核。", "id": "9f1d1809-e614-5579-ad2d-abe92780f8d8"}, {"title": "资治通鉴·卷291·广顺三年六月至十二月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a03e158968cf63490b7ea1d52bdaea928e33b44d/content/books/zizhi-tongjian/vol-291/year-0953/part-03/sources/library/tongjian-291-953-june-december/source.txt", "note": "《资治通鉴》卷291·广顺三年六月至十二月，段落 zizhi-tongjian-a63549944a71-p003458；已核上下文及传主，纸本及异文待核。", "id": "ef9b7b67-6d1a-52f9-b2db-fffd976d2c68"}]'::jsonb)
