INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "刘言", "aliases": ["劉言"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吉州庐陵人，楚国辰州刺史。951年王逵、周行逢等欲迎他到朗州任副使，他单骑前往，众人废去马光惠后推他为权武平留后。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b32e335e-b386-5ab9-a996-bb31d55c6787"}, {"name": "翟光裔", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周通事舍人。953年八月奉命赴湖南宣抚，朝廷同时准许王逵迁使府。未与不同职衔、已去世的翟光邺合并，生卒年未载。", "biography": null, "status": "draft", "id": "609a7dd8-48a4-5e61-9fd5-03cde2408d43"}, {"name": "周行逢", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军副使。951年与王逵率修府士兵逃回朗州。《宋史》记为朗州武陵人，早年因犯法被编入军队，凭骁勇升任军官。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22"}, {"name": "潘叔嗣", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州人、刘言麾下牙将。952年任指挥使。史书称其果敢，与周行逢、张文表交好、共同成事。生卒年未载。", "biography": null, "status": "draft", "id": "0aa70d0f-a11c-50f9-a0e8-3e0a7278f26d"}, {"name": "白重赞", "aliases": ["白重贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周武成节度使。953年九月己亥奏报已堵塞决口的黄河。生卒年未载。", "biography": null, "status": "draft", "id": "b6889cb5-a3c4-5b6a-aa6e-7feda1afc895"}, {"name": "刘彦章", "aliases": ["劉彥章"], "era": "五代十国", "birth_year": null, "death_year": 953, "description": "齐州驻乐寿的保宁军都头。953年杀死兵马都监杜延熙，企图响应契丹，未成而被捕处死。生年未载。", "biography": null, "status": "draft", "id": "a6a23aaa-4c88-51db-a5ff-9ddf0533c29a"}, {"name": "杜延熙", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 953, "description": "乐寿县兵马都监。953年九月被齐州保宁驻军都头刘彦章等杀死。生年未载。", "biography": null, "status": "draft", "id": "fc44a30c-917c-5fc5-afb2-7d66c0a515d5"}, {"name": "马谔", "aliases": ["馬諤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周供奉官。953年奉朝廷命赴乐寿调查，与张万友捕获并处死刘彦章等十三人。生卒年未载。", "biography": null, "status": "draft", "id": "7c3510a3-3219-5b05-b3de-bde3dbc61a20"}, {"name": "张万友", "aliases": ["張萬友"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周郑州开道指挥使。953年驻乐寿，没有参加刘彦章叛乱，与马谔捕获刘彦章等并处死。生卒年未载。", "biography": null, "status": "draft", "id": "87d626ae-1489-5408-ae82-f11c89d69b9c"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘继兴", "aliases": ["劉繼興", "刘鋹", "劉鋹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉刘晟之子，953年封卫王。《新五代史》明确记刘鋹初名继兴，保留同人别名；当时尚未即位，生卒年暂未核定。", "biography": null, "status": "draft", "id": "28c53941-c17f-5791-806a-6e3c36a944c3"}, {"name": "刘璇兴", "aliases": ["劉璇興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉刘晟之子，953年封桂王。生卒年未载。", "biography": null, "status": "draft", "id": "b73a6766-6943-5fd8-a55c-f31fc9ddd3cc"}, {"name": "刘庆兴", "aliases": ["劉慶興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉刘晟之子，953年封荆王。生卒年未载。", "biography": null, "status": "draft", "id": "b22b6eb6-a930-5480-8119-fb33e72926be"}, {"name": "刘保兴", "aliases": ["劉保興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉刘晟之子。953年封王，《通鉴》电子本作祯王、《新五代史》作祥王，保留王号异读。生卒年未载。", "biography": null, "status": "draft", "id": "af8117c9-63b1-5790-ba41-9512edb41e90"}, {"name": "刘崇兴", "aliases": ["劉崇興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉刘晟之子，953年封梅王。生卒年未载。", "biography": null, "status": "draft", "id": "1fe8c822-bb5e-5f80-9973-58487e533371"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "王殷（后汉后周将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州籍将领。950年以侍卫步军都指挥使身份奉命驻澶州防备契丹，后来参与后周建国。《旧五代史》记他自称出生在魏州开元寺，籍贯与出生地分开。与晚唐后梁同名王殷分开建档，生卒年本批未录。", "biography": null, "status": "draft", "id": "4b85115a-7337-546f-af4c-9f6bd20f13c6"}, {"name": "何福进", "aliases": ["何福進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：何福进，宿卫军校、力战者。", "biography": null, "status": "draft", "id": "9212470a-66f0-53db-8b65-ab0f833848be"}, {"name": "折德扆", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "折从远（后名折从阮）之子，任府州蕃汉马步都指挥使。950年五月己亥获任府州团练使，《宋史》也明确记其父为从阮。生卒年未载。", "biography": null, "status": "draft", "id": "11515d9f-5a90-5398-9366-6f44b89ca847"}, {"name": "乔赟", "aliases": ["喬贇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉将领。953年十二月进犯府州，被折德扆击退。生卒年未载。", "biography": null, "status": "draft", "id": "bf0afe82-658e-5aff-b8e9-f718671e4a0b"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "南唐严重干旱，井泉干涸，淮河水浅到可涉渡", "start_year": 953, "end_year": 953, "time_original": "953年七月条下至八月限制运粮前，旱灾具体起止未载", "dynasty": "五代十国", "description": "南唐严重干旱，井泉干涸，淮河水浅到可涉渡。", "phases": [], "location_name": "南唐、淮河流域", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "447501e2-698d-5f95-8bfa-fdf8c4e6edfe"}, {"title": "饥民北渡淮河，濠州与寿州出兵阻拦，饥民与军队冲突后向北逃来", "start_year": 953, "end_year": 953, "time_original": "953年南唐旱灾期间", "dynasty": "五代十国", "description": "饥民北渡淮河，濠州与寿州出兵阻拦，饥民与军队冲突后向北逃来。", "phases": [], "location_name": "濠州、寿州至淮河北岸", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "63be7ee1-9a1f-5e73-b386-3ed9988a98aa"}, {"title": "郭威称两国百姓应同等看待，准许南唐百姓买米运过淮河", "start_year": 953, "end_year": 953, "time_original": "953年七月至八月己未以前，具体许可日未载", "dynasty": "五代十国", "description": "郭威称两国百姓应同等看待，准许南唐百姓买米运过淮河。", "phases": [], "location_name": "后周、淮河", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c6da4269-11a2-5acc-81ce-e3f55e93081d"}, {"title": "南唐人随之建仓大量购粮，供给军队", "start_year": 953, "end_year": 953, "time_original": "953年郭威允许购粮之后、八月己未限制以前", "dynasty": "五代十国", "description": "南唐人随之建仓大量购粮，供给军队。", "phases": [], "location_name": "南唐、淮河一带", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b203d92f-bb58-552c-b51d-b08efc36c603"}, {"title": "郭威准许南唐百姓以人力或牲畜携米，禁止